gtN(){return"\u0414\u043e\u0441\u0442\u0443\u043f\u043d\u044b \u043d\u0430 \u041f\u041a / \u0431\u043e\u043b\u044c\u0448\u043e\u043c \u044d\u043a\u0440\u0430\u043d\u0435"},
grW(){return"\u041f\u0435\u0440\u0435\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u0432\u043a\u043b\u0430\u0434\u043e\u043a"},
grV(){return"\u041f\u043e\u0438\u0441\u043a"},
grT(){return"\u0417\u0430\u043a\u0440\u044b\u0442\u044c \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0443"},
grU(){return"\u041e\u0431\u043d\u043e\u0432\u0438\u0442\u044c"},
